import type { Register } from 'claude-code'

type Limit = { kind: string; percentUsed: number; resetsAt?: string }
type Context = { percent?: number; tokens?: number; window: number }

// Kolor kropki według zużycia: zielony → żółty → pomarańczowy → czerwony.
const dot = (percent: number | null | undefined) => {
  if (percent === null || percent === undefined) return '⚪'
  if (percent >= 90) return '🔴'
  if (percent >= 75) return '🟠'
  if (percent >= 50) return '🟡'
  return '🟢'
}

const pct = (percent: number) => `${Math.round(percent)}%`

const timeLeft = (iso: string | undefined, now: number) => {
  if (!iso) return ''
  const min = Math.round((Date.parse(iso) - now) / 60000)
  if (!(min > 0)) return ''
  if (min >= 24 * 60) return `${Math.floor(min / 1440)}d ${Math.floor((min % 1440) / 60)}h`
  if (min >= 60) return `${Math.floor(min / 60)}h ${min % 60}m`
  return `${min}m`
}

const tokens = (n: number) =>
  n >= 1_000_000 ? `${+(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${Math.round(n / 1000)}k` : `${n}`

// Desktop dokleja przed wpisem nazwę moda („5h”), więc linia zaczyna się
// od razu od kropki limitu 5h i daje: 5h 🟢 17% 3h 12m | 7d … | CTX …
export const line = (limits: readonly Limit[], context: Context, now: number) => {
  const limit = (kind: string, label: string) => {
    const l = limits.find(x => x.kind === kind)
    if (!l) return `${label}${dot(null)} –`
    const left = timeLeft(l.resetsAt, now)
    return `${label}${dot(l.percentUsed)} ${pct(l.percentUsed)}${left ? ` ${left}` : ''}`
  }
  const ctx =
    context.tokens !== undefined && context.window
      ? `CTX ${dot(context.percent)} ${tokens(context.tokens)}/${tokens(context.window)}`
      : `CTX ${dot(null)} –`

  return `${limit('five_hour', '')} | ${limit('seven_day', '7d ')} | ${ctx}`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const usage = await $.session.usage()
    $.ui.status(line(usage.rateLimits, usage.context, await $.clock.now()))

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    $.ui.status(line(e.rateLimits, e.context, await $.clock.now()))

    return next(e)
  })
}
